/* Reusable extraction; generated by tools/build-reusable-core.py. No campaign seeds. */
(() => {
  'use strict';
  const data = globalThis.ECHO_RULES_DATA;
  if (!data) return;
  const index = globalThis.ECHO_RULES_INDEX || { books: {}, catalog: [] };
  const $ = id => document.getElementById(id);
  let settings;
  let callbacks;
  let currentBook = 'phb';
  let currentPage = 1;
  const chosenBookUrls = new Map();

  function defaults(){return {profile:'2014',supplements:{xan:false,tasha:false},favorites:[],bookmarks:[],notes:{},corrections:{},rulings:[],characterOptions:{},exceptionCatalogVersion:4,exceptions:[]};}
  function normalizeSettings(raw){const base=defaults();if(!raw||typeof raw!=='object')return base;const cut=(v,n=700)=>String(v??'').slice(0,n);return {...base,profile:['2014','mixed'].includes(raw.profile)?raw.profile:'2014',favorites:(raw.favorites||[]).filter(v=>typeof v==='string').slice(0,300),notes:raw.notes||{},corrections:raw.corrections||{},rulings:(raw.rulings||[]).slice(0,150),exceptions:(raw.exceptions||[]).filter(v=>v&&v.id&&v.name).slice(0,100).map(v=>({id:cut(v.id,80),name:cut(v.name,80),text:cut(v.text),source:cut(v.source,100)}))};}
  function node(tag, className, content) {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (content !== undefined) element.textContent = content;
    return element;
  }

  function button(parent, label, action, title) {
    const element = node('button', '', label);
    element.type = 'button';
    if (title) element.title = title;
    element.addEventListener('click', action);
    parent.appendChild(element);
    return element;
  }

  function save() {
    settings = normalizeSettings(settings);
    callbacks.save(settings);
    renderSettings();
    renderResults();
  }

  function bookUrl(book, page) {
    const source = chosenBookUrls.get(book) || new URL(data.books[book].file, location.href.split('#')[0]).href;
    return `${source.split('#')[0]}#page=${page}`;
  }

  function printedToPdf(book, printedPage) {
    if (['mm', 'xan', 'tasha', 'lmop', 'madMage'].includes(book)) {
      const page = Number(printedPage) + (book === 'tasha' ? 2 : book === 'lmop' ? 0 : 1);
      return { page: Math.max(1, Math.min(data.books[book].pages, page)), exact: true };
    }
    if (book === 'echo' || book === 'echoPlayer' || book === 'trista' || book === 'tristaSheet' ||
      book === 'ringgo' || book === 'ringgoSheet' || book === 'dracuseth' || book === 'donavan' || book === 'donavanSheet' || book === 'pebble' || book === 'aldric')
      return { page: printedPage, exact: true };
    const found = index.books?.[book]?.printedToPdf?.[printedPage];
    if (found) return { page: found, exact: true };
    if (book === 'phb' && printedPage === 316) return { page: 293, exact: true };
    if (book === 'phb') {
      const anchors = Object.entries({ ...index.books?.phb?.printedToPdf, 316: 293 })
        .map(([printed, pdf]) => [Number(printed), Number(pdf)]).sort((a, b) => a[0] - b[0]);
      const next = anchors.find(([printed]) => printed > printedPage);
      const prior = [...anchors].reverse().find(([printed]) => printed < printedPage);
      if (prior && next && next[0] - prior[0] === next[1] - prior[1])
        return { page: prior[1] + printedPage - prior[0], exact: true };
    }
    return { page: Math.max(1, Math.min(data.books[book].pages, book === 'phb' ? printedPage - 1 : printedPage)), exact: false };
  }

  function pdfToPrinted(book, page) {
    if (['mm', 'xan', 'tasha', 'lmop', 'madMage'].includes(book))
      return book === 'mm' && page > 353 ? null : Number(page) - (book === 'tasha' ? 2 : book === 'lmop' ? 0 : 1);
    if (['echo', 'echoPlayer', 'trista', 'tristaSheet', 'ringgo', 'ringgoSheet', 'dracuseth', 'donavan', 'donavanSheet', 'pebble', 'aldric'].includes(book)) return page;
    if (book === 'phb' && page === 293) return 316;
    if (book === 'phb') {
      const anchors = Object.entries({ ...index.books?.phb?.pdfToPrinted, 293: 316 })
        .map(([pdf, printed]) => [Number(pdf), Number(printed)]).sort((a, b) => a[0] - b[0]);
      const next = anchors.find(([pdf]) => pdf > page);
      const prior = [...anchors].reverse().find(([pdf]) => pdf < page);
      if (prior && next && next[0] - prior[0] === next[1] - prior[1]) return prior[1] + page - prior[0];
    }
    return index.books?.[book]?.pdfToPrinted?.[page] || null;
  }

  function openPage(book, page, note = '') {
    if (!data.books[book]) return;
    const number = Math.max(1, Math.min(data.books[book].pages, Math.round(Number(page) || 1)));
    currentBook = book;
    currentPage = number;
    $('rules-book').value = book;
    $('rules-page').max = data.books[book].pages;
    $('rules-page').value = number;
    $('rules-viewer-title').textContent = `${data.books[book].title} · PDF page ${number}`;
    $('rules-viewer-note').textContent = note || (pdfToPrinted(book, number) ? `Printed page ${pdfToPrinted(book, number)}` : 'Check the printed page number in the book');
    $('rules-viewer').src = bookUrl(book, number);
    renderToc();
  }

  function openNewTab(book = currentBook, page = currentPage) {
    const link = node('a');
    link.href = bookUrl(book, page);
    link.target = '_blank';
    link.rel = 'noopener';
    link.click();
  }

  function renderSettings() {
    $('rules-profile').value = settings.profile;
    $('rules-xan-enabled').checked = settings.supplements.xan;
    $('rules-tasha-enabled').checked = settings.supplements.tasha;
    const exceptions = $('rules-exceptions');
    exceptions.replaceChildren();
    for (const entry of settings.exceptions) {
      const row = node('div', 'rules-entry-small');
      row.append(node('strong', '', entry.name), node('span', '', entry.text));
      if (entry.source) row.append(node('span', '', `Source: ${entry.source}`));
      const actions = node('div', 'button-row');
      button(actions, 'Edit', () => {
        const name = window.prompt('Exception name:', entry.name);
        if (name === null || !name.trim()) return;
        const text = window.prompt('What differs from the 2014 books?', entry.text);
        if (text === null) return;
        const source = window.prompt('Controlling source:', entry.source);
        if (source === null) return;
        Object.assign(entry, { name: name.trim().slice(0, 80), text: text.trim().slice(0, 700), source: source.trim().slice(0, 100) });
        save();
      });
      button(actions, 'Remove', () => {
        settings.exceptions = settings.exceptions.filter(item => item.id !== entry.id);
        save();
      });
      row.append(actions);
      exceptions.append(row);
    }
    const optionsBox = $('rules-character-options');
    optionsBox.replaceChildren();
    const party = callbacks.getParty?.() || {};
    for (const option of data.characterOptions || []) {
      const status = settings.characterOptions[option.id] || '';
      const character = party[option.characterId];
      const level = Number(character?.level) || 0;
      const row = node('div', 'rules-entry-small');
      row.append(node('strong', '', `${character?.name || option.characterId} · ${option.name}`),
        node('span', '', `Level ${option.level} · ${option.source} · ${status || 'Not chosen'}`),
        node('span', '', option.note));
      const actions = node('div', 'button-row');
      button(actions, 'View source', () => openPage(option.book, option.pdfPage, `Printed page ${option.printedPage}`));
      if (status !== 'planned') button(actions, 'Plan', () => { settings.characterOptions[option.id] = 'planned'; save(); });
      if (status !== 'active') {
        const enable = button(actions, 'Enable now', () => {
          for (const other of data.characterOptions.filter(item => item.characterId === option.characterId &&
            item.group === option.group && item.id !== option.id)) delete settings.characterOptions[other.id];
          settings.characterOptions[option.id] = 'active'; save();
        }, level < option.level ? `Available at level ${option.level}` : 'Record this player choice');
        enable.disabled = level < option.level;
      }
      if (status) button(actions, 'Remove', () => { delete settings.characterOptions[option.id]; save(); });
      row.append(actions); optionsBox.append(row);
    }
    const rulings = $('rules-rulings');
    rulings.replaceChildren();
    if (!settings.rulings.length) rulings.append(node('p', 'help', 'No table rulings recorded yet.'));
    for (const entry of settings.rulings) {
      const row = node('div', 'rules-entry-small');
      row.append(node('strong', '', `${entry.name} · ${entry.date}`), node('span', '', entry.text));
      if (entry.source) row.append(node('span', '', `Source: ${entry.source}`));
      button(row, 'Edit', () => {
        const name = window.prompt('Ruling name:', entry.name);
        if (name === null || !name.trim()) return;
        const text = window.prompt('How does the ruling work?', entry.text);
        if (text === null || !text.trim()) return;
        const source = window.prompt('Source or house rule:', entry.source);
        if (source === null) return;
        Object.assign(entry, { name: name.trim().slice(0, 80), text: text.trim().slice(0, 700),
          source: source.trim().slice(0, 100) || 'House ruling · DM' });
        save();
      });
      button(row, 'Remove', () => { settings.rulings = settings.rulings.filter(item => item.id !== entry.id); save(); });
      rulings.append(row);
    }
    const bookmarks = $('rules-bookmarks');
    bookmarks.replaceChildren();
    if (settings.bookmarks.length) bookmarks.append(node('h3', '', 'Bookmarks'));
    for (const mark of settings.bookmarks) {
      const row = node('div', 'rules-bookmark-row');
      button(row, `${data.books[mark.book].short} ${mark.page} · ${mark.name || 'Bookmark'}`, () => openPage(mark.book, mark.page));
      button(row, '×', () => { settings.bookmarks = settings.bookmarks.filter(item => item !== mark); save(); }, 'Remove bookmark');
      bookmarks.append(row);
    }
  }

  function renderToc() {
    if(!data.books[currentBook]){$('rules-toc').replaceChildren();return;}
    const container = $('rules-toc');
    container.replaceChildren();
    for (const [title, printedPage] of data.books[currentBook].toc) {
      const match = printedToPdf(currentBook, printedPage);
      const row = node('div', 'rules-toc-row');
      button(row, title, () => openPage(currentBook, match.page, match.exact
        ? `Printed page ${printedPage}` : `Near printed page ${printedPage}; check the page number`));
      row.append(node('small', '', `p. ${printedPage}`));
      container.append(row);
    }
  }

  function exceptionActive(book) {
    return settings.profile === 'mixed' || settings.exceptions.some(entry =>
      entry.name.toLowerCase().includes(book));
  }

  function terms(value) {
    return String(value || '').normalize('NFKD').toLowerCase().replace(/[\u0300-\u036f]/g, '')
      .match(/[a-z0-9]{3,}/g)?.filter(word => !['the', 'and', 'for', 'with', 'that', 'from', 'this'].includes(word)) || [];
  }

  function searchPages(query) {
    const words = terms(query);
    if (!words.length) return [];
    const results = [];
    for (const book of ['phb', 'dmg', 'srd']) {
      const list = index.books?.[book]?.terms || {};
      let pages = null;
      for (const word of words) {
        const exact = list[word];
        const choices = exact || Object.keys(list).filter(key => key.startsWith(word)).slice(0, 8).flatMap(key => list[key]);
        const found = new Set(choices || []);
        pages = pages === null ? found : new Set([...pages].filter(page => found.has(page)));
        if (!pages.size) break;
      }
      for (const page of [...(pages || [])].slice(0, 35)) {
        const printed = pdfToPrinted(book, page);
        results.push({ id: `page-${book}-${page}`, title: `${data.books[book].title} · ${printed ? `printed p. ${printed}` : `PDF p. ${page}`}`,
          category: 'page', book, pdfPage: page, tags: [], summary: '', audience: data.books[book].audience,
          source: `${data.books[book].short} PDF p. ${page}`, confidence: 'OCR match · verify in book' });
      }
    }
    return results;
  }

  function allEntries() {
    const custom = settings.rulings.map(ruling => ({ id: ruling.id, title: ruling.name, category: 'rule', book: null,
      tags: ['table ruling'], summary: ruling.text, audience: 'dm', source: ruling.source || `Table ruling · ${ruling.date}`,
      confidence: 'Your table’s ruling' }));
    return [...data.references, ...(index.catalog || []), ...custom];
  }

  function renderResult(entry, container) {
    const row = node('article', 'rules-result');
    const heading = node('div', 'rules-result-title');
    heading.append(node('h3', '', entry.title), node('small', 'rules-result-meta', entry.category.replace('-', ' ').toUpperCase()));
    row.append(heading);
    const meta = [entry.source, entry.confidence, entry.audience === 'dm' ? 'DM only' : 'Player safe'].filter(Boolean).join(' · ');
    row.append(node('div', 'rules-result-meta', meta));
    if (entry.tags?.length) row.append(node('div', 'rules-result-meta', entry.tags.join(' · ')));
    if (entry.summary) row.append(node('p', '', entry.summary));
    const correction = settings.corrections[entry.id];
    if (correction) row.append(node('p', 'rules-result-correction', `DM correction (${correction.date}): ${correction.text}`));
    if (settings.notes[entry.id]) row.append(node('p', 'rules-result-note', `DM note: ${settings.notes[entry.id]}`));
    const actions = node('div', 'button-row');
    const mapped = entry.book && entry.printedPage ? printedToPdf(entry.book, entry.printedPage) : null;
    const page = entry.pdfPage || mapped?.page || null;
    if (entry.book && page) {
      button(actions, 'View page', () => openPage(entry.book, page,
        entry.printedPage ? `${mapped?.exact ? 'Printed' : 'Near printed'} page ${entry.printedPage}${mapped?.exact ? '' : ' · check the page number'}`
          : 'OCR page match · verify in book'));
      button(actions, 'New tab', () => openNewTab(entry.book, page));
    }
    if (entry.alternateBook && entry.alternatePdfPage) button(actions,
      `View ${data.books[entry.alternateBook].short} scan`, () => openPage(entry.alternateBook,
        entry.alternatePdfPage, 'OCR heading candidate · check the printed page'));
    if (entry.category !== 'page') {
      button(actions, settings.favorites.includes(entry.id) ? '★ Pinned' : '☆ Pin', () => {
        settings.favorites = settings.favorites.includes(entry.id)
          ? settings.favorites.filter(id => id !== entry.id) : [...settings.favorites, entry.id];
        save();
      });
      button(actions, settings.notes[entry.id] ? 'Edit note' : 'Add note', () => {
        const answer = window.prompt(`Private note for ${entry.title}:`, settings.notes[entry.id] || '');
        if (answer === null) return;
        if (answer.trim()) settings.notes[entry.id] = answer.trim().slice(0, 1200);
        else delete settings.notes[entry.id];
        save();
      });
      button(actions, correction ? 'Edit correction' : 'Correct entry', () => {
        const answer = window.prompt(`Correct ${entry.title}. The original source remains visible:`, correction?.text || '');
        if (answer === null) return;
        if (answer.trim()) settings.corrections[entry.id] = { text: answer.trim().slice(0, 1200), date: new Date().toLocaleDateString() };
        else delete settings.corrections[entry.id];
        save();
      });
      if (entry.audience === 'player' && entry.summary) button(actions, 'Show on TV', () => callbacks.showHandout(entry));
    }
    row.append(actions);
    container.append(row);
  }

  function renderResults() {
    const container = $('rules-results');
    if (!container) return;
    container.replaceChildren();
    const query = $('rules-search').value.trim();
    const filter = $('rules-category').value;
    const needle = terms(query);
    const matches = allEntries().filter(entry => {
      if (filter === 'pages') return false;
      if (entry.edition === '2024-exception' && !exceptionActive(entry.book)) return false;
      if (entry.book === 'xan' && !settings.supplements.xan && !['donavan-catapult','donavan-toll-the-dead'].includes(entry.id)) return false;
      if (entry.book === 'tasha' && !settings.supplements.tasha &&
        !['donavan-mind-sliver','donavan-scribes'].includes(entry.id)) return false;
      if (filter === 'favorite' ? !settings.favorites.includes(entry.id) : filter !== 'all' && entry.category !== filter) return false;
      if (!needle.length) return filter !== 'all' || settings.favorites.includes(entry.id) || entry.category === 'rule';
      const haystack = terms([entry.title, entry.summary, entry.tags?.join(' '), entry.source, settings.notes[entry.id]].join(' '));
      return needle.every(word => haystack.some(candidate => candidate.startsWith(word)));
    });
    const pages = query && ['all', 'pages'].includes(filter) ? searchPages(query) : [];
    const count = matches.length + pages.length;
    container.append(node('p', 'rules-result-meta', `${count} matching references${index.books?.phb?.terms ? ' · book pages indexed' : ' · book index loading'}`));
    for (const entry of matches.slice(0, 60)) renderResult(entry, container);
    if (matches.length > 60) container.append(node('p', 'rules-empty', `Showing the first 60 of ${matches.length} entries. Narrow the search to see more.`));
    for (const entry of pages.slice(0, 25)) renderResult(entry, container);
    if (pages.length > 25) container.append(node('p', 'rules-empty', 'More book pages match. Add another search word to narrow them.'));
    if (!count) container.append(node('p', 'rules-empty', query ? 'No match yet. Try fewer words or search the book pages.' : 'Search the books or choose a category.'));
  }

  function open() {
    $('rules-scrim').hidden = false;
    $('rules-drawer').hidden = false;
    if (!$('rules-viewer').getAttribute('src')) openPage(currentBook, currentPage);
    $('rules-search').focus();
  }

  function close() {
    $('rules-scrim').hidden = true;
    $('rules-drawer').hidden = true;
    document.querySelector('.header-menu summary')?.focus();
  }

  function init(options) {
    callbacks = options;
    $('rules-book').replaceChildren();
    const option=document.createElement('option');option.textContent='No reference pack installed';option.value='';$('rules-book').append(option);
    for(const id of ['rules-open-page','rules-new-tab','rules-bookmark-page','rules-book-file'])$(id).disabled=true;
    settings = normalizeSettings(options.settings);
    $('open-rules').addEventListener('click', open);
    $('close-rules').addEventListener('click', close);
    $('rules-scrim').addEventListener('click', close);
    window.addEventListener('keydown', event => {
      if (event.key === 'Escape' && !$('rules-drawer').hidden) {
        event.stopImmediatePropagation();
        close();
      }
    }, true);
    $('rules-profile').addEventListener('change', event => { settings.profile = event.target.value; save(); });
    $('rules-xan-enabled').addEventListener('change', event => { settings.supplements.xan = event.target.checked; save(); });
    $('rules-tasha-enabled').addEventListener('change', event => { settings.supplements.tasha = event.target.checked; save(); });
    $('rules-search').addEventListener('input', renderResults);
    $('rules-category').addEventListener('change', renderResults);
    $('rules-book').addEventListener('change', event => { currentBook = event.target.value; $('rules-page').max = data.books[currentBook].pages; renderToc(); });
    $('rules-open-page').addEventListener('click', () => openPage($('rules-book').value, $('rules-page').value));
    $('rules-page').addEventListener('keydown', event => { if (event.key === 'Enter') openPage($('rules-book').value, $('rules-page').value); });
    $('rules-new-tab').addEventListener('click', () => openNewTab($('rules-book').value, $('rules-page').value));
    $('rules-bookmark-page').addEventListener('click', () => {
      const book = $('rules-book').value;
      const page = Math.max(1, Math.min(data.books[book].pages, Math.round(Number($('rules-page').value) || 1)));
      const name = window.prompt('Bookmark name:', `${data.books[book].short} page ${page}`);
      if (name === null) return;
      settings.bookmarks.push({ book, page, name: name.trim().slice(0, 100) });
      save();
    });
    $('rules-book-file').addEventListener('change', event => {
      const file = event.target.files?.[0];
      if (!file || (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf'))) return;
      const book = $('rules-book').value;
      if (chosenBookUrls.has(book)) URL.revokeObjectURL(chosenBookUrls.get(book));
      chosenBookUrls.set(book, URL.createObjectURL(file));
      openPage(book, Number($('rules-page').value) || 1, 'Chosen local PDF · page numbers may differ');
    });
    $('rules-add-exception').addEventListener('click', () => {
      const name = $('rules-exception-name').value.trim();
      const text = $('rules-exception-text').value.trim();
      if (!name || !text) { callbacks.toast('Add a name and explanation for the exception.'); return; }
      settings.exceptions.push({ id: `exception-${Date.now()}`, name: name.slice(0, 80), text: text.slice(0, 700),
        source: $('rules-exception-source').value.trim().slice(0, 100) || 'House rule · DM' });
      $('rules-exception-name').value = '';
      $('rules-exception-text').value = '';
      $('rules-exception-source').value = '';
      save();
    });
    $('rules-add-ruling').addEventListener('click', () => {
      const name = $('rules-ruling-name').value.trim();
      const text = $('rules-ruling-text').value.trim();
      if (!name || !text) { callbacks.toast('Add a ruling and how it works.'); return; }
      settings.rulings.unshift({ id: `ruling-${Date.now()}`, name: name.slice(0, 80), text: text.slice(0, 700),
        source: $('rules-ruling-source').value.trim().slice(0, 100) || 'House ruling · DM', date: new Date().toLocaleDateString() });
      $('rules-ruling-name').value = '';
      $('rules-ruling-text').value = '';
      $('rules-ruling-source').value = '';
      save();
    });
    renderSettings();
    renderToc();
    renderResults();
  }

  globalThis.ECHO_RULES_UI = { init, normalizeSettings, printedToPdf, pdfToPrinted, openBook(book, page) {
    open();
    openPage(book, page);
  }, openSearch(query) {
    open();
    $('rules-search').value = query || '';
    renderResults();
  }, optionsForCharacter(id) { return (data.characterOptions || []).filter(option =>
    option.characterId === id && settings?.characterOptions?.[option.id])
    .map(option => ({ ...option, status: settings.characterOptions[option.id] }));
  }, isExceptionActive(book) { return exceptionActive(book); }, setSettings(value) {
    settings = normalizeSettings(value);
    if ($('rules-drawer')) { renderSettings(); renderResults(); }
  } };
})();
